package PerCUDA::Engine::Perl;
use v5.40;
use parent 'PerCUDA::Engine';
use Carp ();
use PerCUDA::CodeGen::Perl;
use PerCUDA::Data qw(zeros copy_array);

# Runs the kernel in the perl interpreter, as Perl code generated by
# PerCUDA::CodeGen::Perl.

my $SERIAL = 0;

sub init ($self) {
    my $package = 'PerCUDA::Engine::Perl::Kernel' . $SERIAL++;
    $self->{perl_source} = "package $package;\nuse strict;\nuse warnings;\nno warnings qw(uninitialized numeric);\n"
        . PerCUDA::CodeGen::Perl->new($self->{analyzer})->generate;
    $self->{code} = eval $self->{perl_source};    ## no critic (ProhibitStringyEval)
    Carp::croak("PerCUDA: failed to compile the kernel for the perl engine: $@\n$self->{perl_source}")
        unless $self->{code};
}

sub name ($self) { 'perl' }

sub perl_source ($self) { $self->{perl_source} }

sub run ($self, @values) {
    my $layout = $self->layout(\@values);
    my @call   = @values;
    for my $i (sort { $a <=> $b } keys %{ $layout->{arrays} }) {
        my $arg = $self->{args}[$i];
        my ($dims, $empty) = @{ $layout->{arrays}{$i} }{qw(dims empty)};
        if ($self->{is_retval}{ $arg->{name} }) {
            @{ $values[$i] } = @{ zeros($dims) } if $empty;    # updated in place, like the GPU engine
        }
        elsif ($empty) {
            $call[$i] = zeros($dims);
        }
        elsif ($arg->{written}) {
            $call[$i] = copy_array($values[$i], $arg->{rank});    # the GPU never copies it back
        }
    }
    $self->{code}->(@call, @{ $layout->{grid} });
    return map { $values[ $self->{index}{$_} ] } @{ $self->{retval} };
}

package PerCUDA::Runtime;
use integer;

# Bit operations on 32-bit signed integers, as on the GPU.
sub _i32 ($v) { unpack 'l', pack 'L', $v & 0xFFFFFFFF }

sub band ($l, $r) { _i32(_i32($l) & _i32($r)) }
sub bor  ($l, $r) { _i32(_i32($l) | _i32($r)) }
sub bxor ($l, $r) { _i32(_i32($l) ^ _i32($r)) }
sub bnot ($v)     { _i32(~_i32($v)) }
sub shl  ($l, $r) { _i32(_i32($l) << _i32($r)) }
sub shr  ($l, $r) { _i32($l) >> _i32($r) }

1;
